/** @vitest-environment node */
import {beforeEach,expect,it,vi} from 'vitest';
const fixture=vi.hoisted(()=>({tenant:'tenant-A',collect:vi.fn()}));
vi.mock('@/lib/auth/currentContext',()=>({currentContext:async()=>({isAuthenticated:true,userId:'synthetic-user',organizationId:fixture.tenant,roles:[]})}));
vi.mock('@/lib/config/env',()=>({loadAppEnv:()=>({githubDefaultOrg:'synthetic-server-global-org'})}));
vi.mock('@/lib/config/features',()=>({serverFeatures:()=>({}),toClientFlags:(flags:unknown)=>flags}));
vi.mock('@/lib/config/providerModes',()=>({getConnectorMode:()=> 'live',getCloudProviderMode:()=> 'preview'}));
vi.mock('@/lib/connectors/github/githubLiveClient',()=>({getGithubMode:()=> 'live'}));
// Only the external live collector is substituted. Actual state aggregation,
// readiness, graph composition and GET/POST handlers remain in this chain.
vi.mock('@/lib/connectors/github/githubLiveScanner',()=>({runLiveGithubSync:fixture.collect}));
// Unrelated deterministic platform signals do not participate in this defect.
vi.mock('@/lib/validation/autonomousValidationLoop',()=>({runAutonomousValidationLoop:async()=>({probes:[]})}));
vi.mock('@/lib/agent/autonomousPlanningLoop',()=>({runAutonomousPlanningLoop:async()=>({candidates:[]})}));
import {GET,POST} from '../route';
const secretRepo='SYNTHETIC_SERVER_PRIVATE_REPOSITORY';
beforeEach(()=>{
 vi.clearAllMocks();fixture.tenant='tenant-A';
 fixture.collect.mockResolvedValue({repos:[{id:'server-private-repo',organization:'synthetic-server-global-org',name:secretRepo,defaultBranch:'main',visibility:'private',pushedAt:'2026-11-01T00:00:00Z',protected:false,source:'live'}],workflows:[],protections:[],durationMs:0,source:'live',limitations:[],authenticatedLogin:'synthetic-server-account'});
});
it.each([['GET',GET],['POST',POST]] as const)('%s must not disclose server-global GitHub diagnostics to unrelated authenticated tenants',async(_method,handler)=>{
 const observations:Array<{tenant:string,status:number,body:string}>=[];
 for(const tenant of ['tenant-A','tenant-B']){
  fixture.tenant=tenant;const response=await handler();const body=await response.json();
  observations.push({tenant,status:response.status,body:JSON.stringify(body)});
 }
 // Diagnostic chain controls: both actual handlers reached the external
 // collector through actual getReleaseOpsState({}) and its server-org default.
 expect(fixture.collect).toHaveBeenCalledTimes(2);
 for(const call of fixture.collect.mock.calls)expect(call[0]).toEqual({organization:'synthetic-server-global-org',maxRepos:undefined});
 expect(observations.map(row=>row.status)).toEqual([200,200]);
 for(const row of observations)expect(row.body).toContain(row.tenant);
 // Desired tenant-isolation invariant. CURRENT SOURCE FAILS: both responses
 // carry a private-server-org branch-protection diagnostic. No repair is made.
 expect(observations.filter(row=>row.body.includes(secretRepo)).map(row=>row.tenant)).toEqual([]);
});
